  ('hint-quiz', '이 동물은 무엇일까요?', '불가사리', '{"category": "동물", "hints": [{"label": "사는 곳", "value": "바다 밑"}, {"label": "특징", "value": "팔이 잘려도 다시 자란다"}, {"label": "먹는 방법", "value": "위를 몸 밖으로 꺼내 조개를 먹는다"}, {"label": "팔", "value": "대부분 다섯 개"}, {"label": "결정적 힌트", "value": "별 모양 바다 동물"}], "aliases": ["starfish"]}'),
  ('hint-quiz', '이 동물은 무엇일까요?', '오징어', '{"category": "동물", "hints": [{"label": "분류", "value": "연체동물"}, {"label": "사는 곳", "value": "바다"}, {"label": "방어 방법", "value": "먹물을 뿜는다"}, {"label": "다리", "value": "10개 (문어는 8개)"}, {"label": "결정적 힌트", "value": "말려서 구워 먹는 간식으로도 유명"}], "aliases": ["squid"]}'),
  ('hint-quiz', '이 동물은 무엇일까요?', '해마', '{"category": "동물", "hints": [{"label": "분류", "value": "어류"}, {"label": "사는 곳", "value": "따뜻한 바다의 해초 숲"}, {"label": "꼬리", "value": "꼬리로 해초를 붙잡고 있다"}, {"label": "놀라운 사실", "value": "수컷이 배 주머니에서 새끼를 낳는다"}, {"label": "결정적 힌트", "value": "말 머리를 닮은 물고기"}], "aliases": ["seahorse"]}'),
  ('hint-quiz', '이 동물은 무엇일까요?', '반딧불이', '{"category": "동물", "hints": [{"label": "분류", "value": "곤충"}, {"label": "활동 시간", "value": "여름밤"}, {"label": "사는 곳", "value": "물이 깨끗한 곳에만 산다"}, {"label": "다른 이름", "value": "개똥벌레"}, {"label": "결정적 힌트", "value": "배 끝에서 반짝반짝 빛이 난다"}], "aliases": ["개똥벌레", "반딧불", "firefly"]}'),
  ('hint-quiz', '이 동물은 무엇일까요?', '달팽이', '{"category": "동물", "hints": [{"label": "분류", "value": "연체동물"}, {"label": "움직임", "value": "끈적한 점액을 내며 기어간다"}, {"label": "눈", "value": "더듬이 끝에 달려 있다"}, {"label": "놀라운 사실", "value": "한 몸에 암컷과 수컷이 함께 있다"}, {"label": "결정적 힌트", "value": "등에 빙글빙글 껍데기를 지고 다닌다"}], "aliases": ["snail"]}'),
  ('hint-quiz', '이 동물은 무엇일까요?', '코뿔소', '{"category": "동물", "hints": [{"label": "분류", "value": "포유류"}, {"label": "사는 곳", "value": "아프리카·아시아"}, {"label": "피부", "value": "두껍고 주름진 갑옷 같은 피부"}, {"label": "놀라운 사실", "value": "뿔은 머리카락과 같은 성분(케라틴)"}, {"label": "결정적 힌트", "value": "코 위에 커다란 뿔"}], "aliases": ["rhino", "rhinoceros"]}'),
  ('hint-quiz', '이 동물은 무엇일까요?', '늑대', '{"category": "동물", "hints": [{"label": "분류", "value": "포유류 (갯과)"}, {"label": "생활", "value": "무리를 지어 함께 사냥한다"}, {"label": "관계", "value": "개의 조상"}, {"label": "동화", "value": "빨간 모자, 아기 돼지 삼형제의 악당"}, {"label": "결정적 힌트", "value": "달밤에 ''아우~'' 하고 운다"}], "aliases": ["wolf"]}'),
  ('hint-quiz', '이 동물은 무엇일까요?', '여우', '{"category": "동물", "hints": [{"label": "분류", "value": "포유류 (갯과)"}, {"label": "생김새", "value": "뾰족한 귀와 풍성한 꼬리"}, {"label": "옛이야기", "value": "꼬리가 아홉 개 달린 구미호"}, {"label": "이솝 우화", "value": "포도를 못 따 먹자 ''저건 신 포도야''"}, {"label": "결정적 힌트", "value": "꾀가 많은 동물로 유명"}], "aliases": ["fox"]}');
