-- 힌트 퀴즈 시드 데이터 (직접 만든 문제 116개 — 축구선수 8·동물 50·나라 8·음식 50)
-- 힌트는 막연한 것 → 구체적인 것 순서 (게임이 마지막에 '이름 초성' 힌트를 자동으로 붙인다).
-- 축구선수 소속팀은 현 소속팀이 아니라 대표적인 팀.
-- 여러 번 실행해도 결과가 같도록 이 파일의 문제만 지우고 다시 넣는다. (점수 기록은 유지)
-- 위키데이터로 자동 생성한 문제(meta.source = wikidata)는 장르별 파일이 따로 관리한다: 축구선수 hint-quiz-football.sql, 야구선수 hint-quiz-baseball.sql, 나라 hint-quiz-country.sql
-- 적용: pnpm db:seed:local (seeds/*.sql 전체가 파일명 순서대로 적용됨)

INSERT OR IGNORE INTO game (id, name, category) VALUES ('hint-quiz', '힌트 퀴즈', 'quiz');

DELETE FROM quiz_item WHERE game_id = 'hint-quiz' AND json_extract(meta, '$.source') IS NULL;


